verify.cmd:
node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const strip=(s)=>s.replace(/^\s*--.*$/gm," ")
const migs=fs.readdirSync("supabase/migrations").filter((f)=>f.endsWith(".sql")).sort().map((f)=>strip(fs.readFileSync("supabase/migrations/"+f,"utf8"))).join("\n")
const grid=rd("app/(main)/admin/library/loom-grid.tsx")
if(grid===null)process.exit(79)
const route=rd("app/api/library/download/[id]/route.ts")
if(route===null)fail("there is no download route, so Download fetches the public URL in the browser and no policy is ever asked")
const door=rd("lib/library/download-door.ts")
if(door===null)fail("the download route has no door module, so nothing applies a policy or writes a record")
const who=route.indexOf("getCallerProfile(")
const open=route.indexOf("openLibraryDownload(")
if(who<0||open<0||who>open)fail("the route does not establish the caller before it opens the door, so the policy has nobody to apply to")
if(!/download_policy/.test(door)||!/policy === .members.|if \(!caller\) return .members./.test(door)||!/authorizeAction\(/.test(door))fail("the door never compares the caller to the policy, so members and staff still mean nothing to it")
const ins=door.indexOf(".from(\x27library_downloads\x27)")
const okAt=door.indexOf("return { ok: true, location }")
if(ins<0)fail("the door writes nothing down, so who took an original is nowhere recorded")
if(okAt<0||okAt<ins)fail("the door answers before it records, so a download that could not be written down still leaves")
if(!/if \(error\) return \{ ok: false, refusal: .unrecorded. \}/.test(door))fail("a failed record does not refuse the download")
const ttl=/LIBRARY_DOWNLOAD_TTL_SECONDS = (\d+)/.exec(door)
if(!ttl||Number(ttl[1])>60)fail("the door signs a protected original for longer than a minute")
if(!/signedLibraryAssetUrl\(asset, LIBRARY_DOWNLOAD_TTL_SECONDS/.test(door))fail("the door does not sign a protected original with its one-minute life")
if(!/create table if not exists public\.library_downloads/.test(migs))fail("no migration creates public.library_downloads, so the audit has no table")
if(/create policy[^;]*\son public\.library_downloads\s+for\s+(insert|update|delete|all)/i.test(migs))fail("the download record can be written, rewritten or deleted by a caller, so it is not a record")
if(!/\/api\/library\/download\//.test(grid))fail("the drawer still downloads the public URL directly, so the route exists and the button bypasses it")
if(/downloadImageUrl\(/.test(grid))fail("the drawer still fetches the file in the browser beside the door")
console.log("ok")'
